 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {v: sum(row.count(v) for row in g) for v in {x for row in g for x in row}}
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)
    accent = 4
    # Find rectangular outlines (two vertical sides joined by horizontal
    # strokes), then color their enclosed area, including interruptions in
    # the top/bottom strokes.
    for top in range(h):
        for bottom in range(top + 2, h):
            for left in range(w):
                if g[top][left] != fg or g[bottom][left] != fg:
                    continue
                for right in range(left + 2, w):
                    if g[top][right] != fg or g[bottom][right] != fg:
                        continue
                    if all(g[r][left] == fg and g[r][right] == fg for r in range(top, bottom + 1)):
                        if all(any(g[top][c] == fg for c in range(left, right + 1)) and any(g[bottom][c] == fg for c in range(left, right + 1)) for _ in [0]):
                            # Paint only if the frame contains a nonempty background interior.
                            if any(g[r][c] == bg for r in range(top, bottom + 1) for c in range(left, right + 1)):
                                for r in range(top, bottom + 1):
                                    for c in range(left, right + 1):
                                        if g[r][c] == bg:
                                            g[r][c] = accent
    return g

